void xfs_da_fix_hashpath(struct xfs_da_state *state, struct xfs_da_state_path *path) {
    struct xfs_da_intnode *node;
    struct xfs_dir2_data_entry *entry;
    struct xfs_da_geometry *geo = state->mp->m_dagen;
    int level;
    int i;

    for (level = path->active_levels - 1; level >= 0; level--) {
        switch (be16_to_cpu(path->atl[level].magic)) {
            case XFS_DA_NODE_MAGIC:
                node = path->atl[level].bp->b_addr;
                for (i = 0; i < geo->node_ents[level]; i++) {
                    if (be32_to_cpu(node->hashval[i]) == state->hashval) {
                        state->intnode = node;
                        state->index = i;
                        state->active = level;
                        return;
                    }
                }
                break;
            case XFS_DIR2_DATA_MAGIC:
                entry = path->atl[level].u.data_entry;
                if (entry && be32_to_cpu(entry->hashval) == state->hashval) {
                    state->datap = entry;
                    state->index = 0;
                    state->active = level;
                    return;
                }
                break;
            default:
                break;
        }
    }
}

void xfs_da_fix_hash_path(struct xfs_da_state *state, struct xfs_da_state_path *path) {
    struct xfs_da_intnode *node;
    struct xfs_dir2_leaf *leaf;
    struct xfs_dir2_block *block;
    struct xfs_da_state_path *tpath;
    struct xfs_da_state *tstate;
    __u16 hashval, lasthash;
    int i, j;
    int level;

    lasthash = 0;

    for (i = path->active; i > 0; i--) {
        node = path->path[i - 1].bp->data;
        if (be32_to_cpu(node->magic) == XFS_DIR2_LEAFN_MAGIC) {
            leaf = (struct xfs_dir2_leaf *)node;
            hashval = be16_to_cpu(leaf->hdr.info.firsthash);
            if (lasthash != hashval) {
                xfs_da_log_leaf(state->args->tp, path->path[i - 1].bp, XFS_DA_LOG_CHANGE);
                leaf->hdr.info.firsthash = cpu_to_be16(lasthash);
            }
            lasthash = be16_to_cpu(leaf->hdr.info.lasthash);
        } else if (be32_to_cpu(node->magic) == XFS_DIR2_BLOCK_MAGIC) {
            block = (struct xfs_dir2_block *)node;
            hashval = be16_to_cpu(block->hdr.info.firsthash);
            if (lasthash != hashval) {
                xfs_da_log_data(state->args->tp, path->path[i - 1].bp, XFS_DA_LOG_CHANGE);
                block->hdr.info.firsthash = cpu_to_be16(lasthash);
            }
            lasthash = be16_to_cpu(block->hdr.info.lasthash);
        } else {
            for (j = node->count; j > 0; j--) {
                hashval = be16_to_cpu(node->hashval[j - 1]);
                if (lasthash != hashval) {
                    xfs_da_log_node(state->args->tp, path->path[i - 1].bp, XFS_DA_LOG_CHANGE);
                    node->hashval[j - 1] = cpu_to_be16(lasthash);
                }
                lasthash = hashval;
            }
        }
    }
}

void xfs_da_fix_hashpath(struct xfs_da_state *state, struct xfs_da_state_path *path)
{
	struct xfs_da_intnode *node;
	struct xfs_dir2_data_hdr *hdr;
	struct xfs_da_node_hdr *nhdr;
	uint32_t hashval;
	int i, j, level;

	/*
	 * Get the last hash value from the leaf node.  We have to check the
	 * magic number to determine the type of the block.
	 */
	node = path->path_entry[state->stateno].bp->data;
	if (be32_to_cpu(node->magic) == XFS_DA_NODE_MAGIC)
		hashval = be32_to_cpu(node->hashval[0]);
	else if (be32_to_cpu(node->magic) == XFS_DIR2_LEAFN_MAGIC)
		hashval = be32_to_cpu(((struct xfs_dir2_leaf *)node)->head_hashval[0]);
	else {
		hdr = path->path_entry[state->stateno].bp->data;
		hashval = be32_to_cpu(hdr->magic) == XFS_DIR2_DATA_MAGIC ?
			  be32_to_cpu(((struct xfs_dir2_data_entry *)((char *)hdr +
								   sizeof(*hdr)))->hashval) :
			  be32_to_cpu(((struct xfs_dir2_data_free_entry *)((char *)hdr +
									sizeof(*hdr)))->hashval);
	}

	/* Walk up the tree and update the hash values. */
	for (level = state->stateno - 1; level >= 0; level--) {
		node = path->path_entry[level].bp->data;
		nhdr = (struct xfs_da_node_hdr *)node;
		for (i = 0; i < be16_to_cpu(nhdr->count); i++) {
			for (j = 0; j < be16_to_cpu(nhdr->count); j++) {
				if (be32_to_cpu(node->hashval[j]) == hashval)
					break;
			}
			if (j < be16_to_cpu(nhdr->count))
				break;
		}

		if (i == be16_to_cpu(nhdr->count))
			break;

		node->hashval[i] = cpu_to_be32(hashval);
		hashval = be32_to_cpu(node->hashval[i - 1]);

		/* Log the change. */
		xfs_trans_log_block(state->trans, path->path_entry[level].bp,
				    XFS_DA_LOG_CHANGE);
	}
}

void xfs_da_fix_hash_path(struct xfs_da_state *state, struct xfs_da_state_path *path)
{
    struct xfs_da_intnode *node;
    struct xfs_dir2_leaf *leaf;
    struct xfs_dir2_data_hdr *hdr;
    int level, blockno;
    __be32 hashval;
    int i;

    level = path->active_levels - 1;
    blockno = path->at[level].blkno;
    hashval = path->at[level].hashval;

    for (i = level; i >= 0; i--) {
        switch (be32_to_cpu(path->at[i].magic)) {
        case XFS_DA_NODE_MAGIC:
            node = path->at[i].intnode;
            node->hashval = hashval;
            xfs_da_log_intnode(state->args->tp, node, 0, 1);
            break;
        case XFS_DIR2_LEAFN_MAGIC:
            leaf = path->at[i].leaf;
            leaf->hdr.info.magic = cpu_to_be32(XFS_DIR2_LEAFN_MAGIC);
            leaf->hdr.hashval = hashval;
            xfs_da_log_leaf(state->args->tp, leaf, 0, 1);
            break;
        case XFS_DIR2_DATAN_MAGIC:
            hdr = path->at[i].data;
            hdr->magic = cpu_to_be32(XFS_DIR2_DATAN_MAGIC);
            hdr->hashval = hashval;
            xfs_da_log_data(state->args->tp, hdr, 0, 1);
            break;
        }
    }
}

void xfs_da_fix_hashpath(struct xfs_da_state *state, struct xfs_da_state_path *path)
{
    struct xfs_da_intnode *node;
    xfs_dahash_t hash;
    int i, j;

    hash = xfs_da_get_hashval(path->path_val, path->path_active);

    for (i = path->path_levels - 1; i >= 0; i--) {
        node = path->path_node[i];
        for (j = path->path_index[i] - 1; j >= 0; j--) {
            if (be16_to_cpu(node->hdr.info.geo.magic) == XFS_DA_NODE_MAGIC)
                hash = node->bnode.bp[j + 1];
            else
                hash = node->leaf.bp[j + 1].hashval;
            if (hash == 0)
                break;
        }
        if (hash == 0)
            break;
    }

    for (; i >= 0; i--) {
        node = path->path_node[i];
        if (be16_to_cpu(node->hdr.info.geo.magic) == XFS_DA_NODE_MAGIC)
            node->bnode.hashval = cpu_to_be32(hash);
        else
            node->leaf.hashval = cpu_to_be32(hash);
        xfs_da_log_change(state->args->trans, node, XFS_DA_LOG_RES_BLOCK);
    }
}
